"""Regenerates atlas-ml-smoketest.{onnx,json}, the fixture the TEST_ONNXRUNTIME_LIB_PATH-gated
integration tests in ../onnx_integration_test.go load.

Committed so the fixture is reproducible rather than an opaque binary nobody can rebuild. Run it
whenever ml.FeatureOrder changes — the .onnx graph encodes the input width, so a feature added to
the Go side without regenerating here leaves a model that loads fine and then fails at the first
inference. That is exactly what happened once: the sidecar was updated from 5 features to 8 while
the graph stayed at 5, and because the tests skip without a native onnxruntime, nothing noticed
until CI was given the library.

Run inside the training image so the pinned converter stack matches production's:

    docker run --rm -v "$PWD":/src -w /src atlas-trainer-deps \
        python internal/application/ml/testdata/gen_smoketest.py

The data is synthetic. The tests assert only that a real probability comes back, not that it is
accurate — real model quality is training/train.py's holdout metrics, not a Go test's business.
"""
import json
import time

import numpy as np
from onnxmltools.convert import convert_xgboost
from onnxmltools.convert.common.data_types import FloatTensorType
from xgboost import XGBClassifier

# Must stay identical to ml.FeatureOrder in ../onnx.go, in the same order.
FEATURE_ORDER = ["rsi", "ema_dist", "macd_pct", "tr_pct", "atr_pct", "rvol_20", "rvol_50", "volume"]
OUT = "internal/application/ml/testdata/atlas-ml-smoketest"
STALE_OUT = "internal/application/ml/testdata/atlas-ml-stale-graph"

rng = np.random.default_rng(20260815)
n = 400
split = 320

# Synthetic but not pure noise: the label leans on rsi and atr_pct so the trees have something to
# split on and the exported graph returns a non-degenerate probability rather than a constant.
X = np.column_stack([
    rng.uniform(10, 90, n),        # rsi
    rng.normal(0, 0.03, n),        # ema_dist
    rng.normal(0, 0.01, n),        # macd_pct
    rng.uniform(0.002, 0.05, n),   # tr_pct
    rng.uniform(0.005, 0.06, n),   # atr_pct
    rng.uniform(0.3, 3.0, n),      # rvol_20
    rng.uniform(0.3, 3.0, n),      # rvol_50
    rng.uniform(0.2, 4.0, n),      # volume
]).astype(np.float32)

score = (X[:, 0] - 50) / 40 + (X[:, 4] - 0.03) * 8 + rng.normal(0, 0.4, n)
y = (score > 0.5).astype(int)

model = XGBClassifier(n_estimators=12, max_depth=3, learning_rate=0.3, eval_metric="logloss")
model.fit(X[:split], y[:split])

# Same converter, input name and shape train.py uses, so the fixture exercises the real export
# path rather than a simplified stand-in.
onnx_model = convert_xgboost(
    model,
    initial_types=[("features", FloatTensorType([None, len(FEATURE_ORDER)]))],
)
with open(f"{OUT}.onnx", "wb") as f:
    f.write(onnx_model.SerializeToString())

# A second, deliberately inconsistent fixture: a graph trained on the pre-vol-feature 5-input
# layout, paired with a sidecar claiming the current 8. That is the exact broken state the real
# fixture was found in, and it is what ../onnx.go's graphFeatureWidthMatches exists to reject —
# the sidecar check alone waves it straight through. Kept small on purpose; it is never used for
# inference, only to prove the loader refuses it.
stale_model = XGBClassifier(n_estimators=4, max_depth=2, learning_rate=0.3, eval_metric="logloss")
stale_model.fit(X[:split, :5], y[:split])
stale_onnx = convert_xgboost(
    stale_model,
    initial_types=[("features", FloatTensorType([None, 5]))],
)
with open(f"{STALE_OUT}.onnx", "wb") as f:
    f.write(stale_onnx.SerializeToString())
with open(f"{STALE_OUT}.json", "w") as f:
    json.dump({
        "version": "stale-graph",
        "trained_at": time.time(),
        # Deliberately the current 8, disagreeing with the 5 the graph above declares.
        "feature_order": FEATURE_ORDER,
        "label_definition": "fixture for the graph/sidecar mismatch guard; never used for inference",
    }, f, indent=2)

holdout_prob = model.predict_proba(X[split:])[:, 1]
counts = np.bincount(y, minlength=2)
metadata = {
    "version": "smoketest",
    "trained_at": time.time(),
    "feature_order": FEATURE_ORDER,
    "row_count": int(n),
    "train_row_count": int(split),
    "holdout_row_count": int(n - split),
    "label_distribution": {"0": int(counts[0]), "1": int(counts[1])},
    "holdout_accuracy": float((holdout_prob.round() == y[split:]).mean()),
    "label_definition": (
        "synthetic fixture, not a real label: generated by testdata/gen_smoketest.py purely to "
        "exercise the export/load/inference mechanics end to end"
    ),
}
with open(f"{OUT}.json", "w") as f:
    json.dump(metadata, f, indent=2)

print(f"wrote {OUT}.onnx and {OUT}.json with {len(FEATURE_ORDER)} features")
print(f"wrote {STALE_OUT}.onnx (5-feature graph) and {STALE_OUT}.json (claims 8) for the mismatch guard")
